// ===== Einstellungen · E-Rechnung prüfen (KoSIT) · nur hier anpassen =====
// Prüft XRechnung (XML) und ZUGFeRD/Factur-X (PDF mit eingebettetem XML) technisch gegen EN 16931.
// Ergebnis ist ein technischer Befund für Buchhaltung oder Kanzlei – kein Steuer- oder Rechtsurteil.
const konfig = {
  eingang: '/data/erechnung/eingang',          // ANPASSEN: Ordner mit Rechnungen (PDF/XML)
  berichte: '/data/erechnung/pruefberichte',   // deutscher Prüfbericht je Rechnung (HTML), nach Monat
  protokoll: '/data/erechnung/protokoll',      // CSV je Monat + Merkliste bereits geprüfter Dateien
  validatorUrl: 'http://kosit:8080/',          // ANPASSEN: KoSIT-Validator im Daemon-Modus, nur im eigenen Netz
};
return [{ json: { konfig } }];

// Liest neue PDF- und XML-Dateien aus dem Eingangsordner. Bereits geprüfte Dateien (Name + Änderungszeit) werden übersprungen.
// Aus PDFs wird das eingebettete XML (ZUGFeRD/Factur-X) gelesen; PDFs ohne XML sind keine E-Rechnung und werden nur protokolliert.
const fs = require('fs'); const path = require('path'); const zlib = require('zlib');
const k = $('Einstellungen').first().json.konfig;
fs.mkdirSync(k.protokoll, { recursive: true });
const merk = path.join(k.protokoll, 'geprueft.json');
let gesehen = {}; try { gesehen = JSON.parse(fs.readFileSync(merk, 'utf8')); } catch (e) {}
function xmlAusPdf(buf) {
  const s = buf.toString('latin1'); let pos = 0;
  while (true) {
    const a = s.indexOf('stream', pos); if (a < 0) break;
    const b = s.indexOf('endstream', a); if (b < 0) break;
    let start = a + 6; if (s[start] === '\r') start++; if (s[start] === '\n') start++;
    const roh = buf.subarray(start, b); pos = b + 9;
    if (roh.length < 40) continue;
    const kandidaten = [];
    try { kandidaten.push(zlib.inflateSync(roh).toString('utf8')); } catch (e) { try { kandidaten.push(zlib.inflateRawSync(roh).toString('utf8')); } catch (e2) {} }
    kandidaten.push(roh.toString('utf8'));
    for (const text of kandidaten) {
      const t = text.replace(/^﻿/, '').trimStart();
      if (/^<\?xml|^<rsm:|^<Invoice|^<ubl:/.test(t) && /CrossIndustryInvoice|urn:oasis:names:specification:ubl/.test(t)) return t;
    }
  }
  return '';
}
const out = [];
for (const name of fs.readdirSync(k.eingang).filter(f => /\.(pdf|xml)$/i.test(f)).sort()) {
  const voll = path.join(k.eingang, name);
  const schluessel = name + '|' + fs.statSync(voll).mtimeMs;
  if (gesehen[schluessel]) continue;
  const buf = fs.readFileSync(voll);
  const istXml = /\.xml$/i.test(name);
  const xml = istXml ? buf.toString('utf8').replace(/^﻿/, '') : xmlAusPdf(buf);
  out.push({ json: { datei: name, schluessel, xml, hatXml: !!xml } });
}
return out.length ? out : [{ json: { leer: true } }];

// ===== KoSIT-Validator · EN 16931 / XRechnung =====
// Schickt jeden XML-Datensatz an den KoSIT-Validator und legt den deutschen Prüfbericht ab.
// Ein abgelehnter Datensatz ist ein HINWEIS, kein Stopp: Ob die Rechnung so angenommen wird, entscheidet die Buchhaltung bzw. Kanzlei.
const fs = require('fs'); const path = require('path');
const k = $('Einstellungen').first().json.konfig;
const url = k.validatorUrl;
const mon = $now.setZone('Europe/Berlin').toFormat('yyyy-MM');
const berichtDir = path.join(k.berichte, mon);
const csvDatei = path.join(k.protokoll, 'erechnung-' + mon + '.csv');
const merk = path.join(k.protokoll, 'geprueft.json');
const pz = s => String(s == null ? '' : s).replace(/[;\r\n]+/g, ' ').trim();
const csvZeile = f => { if (!fs.existsSync(csvDatei)) fs.writeFileSync(csvDatei, '﻿Zeitpunkt;Datei;Szenario;Ergebnis;Fehler;Warnungen;Regeln;Pruefbericht\n'); fs.appendFileSync(csvDatei, f.map(pz).join(';') + '\n'); };

async function sende(xml, name) {
  const opt = { method: 'POST', url: url + encodeURIComponent(name), body: xml, headers: { 'Content-Type': 'application/xml' },
                json: false, returnFullResponse: true, ignoreHttpStatusErrors: true, timeout: 60000 };
  try { const r = await this.helpers.httpRequest(opt); return { status: r.statusCode, text: String(r.body || '') }; }
  catch (e) {
    if (typeof fetch !== 'function') throw e;
    const r = await fetch(opt.url, { method: 'POST', body: xml, headers: opt.headers });
    return { status: r.status, text: await r.text() };
  }
}
function auswerten(text) {
  const meldungen = [];
  for (const m of text.matchAll(/<rep:message\b([^>]*)>([\s\S]*?)<\/rep:message>/g)) {
    const a = m[1], level = (a.match(/level="([^"]*)"/) || [])[1] || '', code = (a.match(/code="([^"]*)"/) || [])[1] || '';
    meldungen.push({ level, code, text: m[2].replace(/<[^>]+>/g, '').replace(/\s+/g, ' ').trim() });
  }
  const i = text.indexOf('<rep:scenarioMatched>');
  const szenario = i >= 0 ? ((text.slice(i).match(/<s:name>([^<]*)<\/s:name>/) || [])[1] || '') : 'kein passendes Szenario';
  const e = text.indexOf('<rep:explanation>'), f = text.indexOf('</rep:explanation>');
  const html = e >= 0 && f > e ? text.slice(e + 17, f) : '';
  return { meldungen, szenario, html };
}

const sendeGebunden = sende.bind(this);
let gesehen = {}; try { gesehen = JSON.parse(fs.readFileSync(merk, 'utf8')); } catch (e) {}
const out = [];
for (const item of $input.all()) {
  const j = item.json;
  if (j.leer) continue;
  let er;
  if (!j.hatXml) {
    er = { ergebnis: 'keine E-Rechnung (PDF ohne XML-Datensatz)', szenario: '', fehler: 0, warnungen: 0, regeln: [], meldungen: [], bericht: '' };
  } else {
    try {
      const r = await sendeGebunden(j.xml, j.datei.replace(/\.[^.]+$/, '') + '.xml');
      const a = auswerten(r.text);
      const fehler = a.meldungen.filter(m => m.level === 'error'), warn = a.meldungen.filter(m => m.level === 'warning');
      const ergebnis = r.status === 200 ? 'gültig' : r.status === 406 ? 'abgelehnt' : 'nicht geprüft (HTTP ' + r.status + ')';
      let bericht = '';
      if (a.html) {
        fs.mkdirSync(berichtDir, { recursive: true });
        bericht = path.join(berichtDir, j.datei.replace(/\.[^.]+$/, '') + '_Pruefbericht.html');
        fs.writeFileSync(bericht, '<!doctype html>' + a.html);
      }
      er = { ergebnis, szenario: a.szenario, fehler: fehler.length, warnungen: warn.length, regeln: [...new Set(fehler.map(m => m.code).filter(Boolean))], meldungen: fehler.slice(0, 5).map(m => m.text), bericht };
    } catch (e) {
      er = { ergebnis: 'nicht geprüft (Validator nicht erreichbar)', szenario: '', fehler: 0, warnungen: 0, regeln: [], meldungen: [String(e.message || e)], bericht: '' };
    }
  }
  csvZeile([$now.setZone('Europe/Berlin').toFormat('yyyy-MM-dd HH:mm:ss'), j.datei, er.szenario, er.ergebnis, er.fehler, er.warnungen, er.regeln.join(' '), er.bericht]);
  if (!er.ergebnis.startsWith('nicht geprüft')) gesehen[j.schluessel] = $now.toISO();   // nicht erreichbar → beim nächsten Lauf erneut
  out.push({ json: { datei: j.datei, ...er } });
}
fs.writeFileSync(merk, JSON.stringify(gesehen, null, 1));
return out.length ? out : [{ json: { hinweis: 'Keine neuen Dateien im Eingang.' } }];
